type User {
  id: ID!
  displayName: String!
  avatarUrl: String
  orders(first: Int = 20, after: String): OrderConnection!
}

type Query { user(id: ID!): User }

interface Node { id: ID! }
union SearchResult = User | Order
enum OrderStatus { PENDING PAID CANCELLED }
input OrderFilter { status: [OrderStatus!]; createdAfter: DateTime }

type Product {
  price: Money!
  legacyPriceCents: Int @deprecated(reason: "Use price")
}
type Money { amount: Decimal! currency: CurrencyCode! }

query AccountPage($id: ID!, $withOrders: Boolean!) {
  user(id: $id) {
    ...UserSummary
    orders(first: 10) @include(if: $withOrders) { nodes { id total } }
  }
}
fragment UserSummary on User { id displayName avatarUrl }

const resolvers = {
  Query: { user: (_parent, { id }, ctx) => ctx.users.findAuthorized(ctx.viewer, id) },
  User: { orders: (user, args, ctx) => ctx.orders.forUser(user.id, args) },
};

const usersById = new DataLoader(async ids => {
  const users = await repository.findMany(ids);
  const byId = new Map(users.map(user => [user.id, user]));
  return ids.map(id => byId.get(id) ?? new Error(`Missing ${id}`));
});

type OrderConnection { nodes: [Order!]! pageInfo: PageInfo! }
type PageInfo { hasNextPage: Boolean! endCursor: String }

query { orders(first: 20, after: $cursor) { nodes { id } pageInfo { hasNextPage endCursor } } }

input CreateOrderInput { clientMutationId: ID! items: [OrderItemInput!]! }
type CreateOrderPayload { order: Order; problems: [UserProblem!]! }
type Mutation { createOrder(input: CreateOrderInput!): CreateOrderPayload! }

subscription OrderUpdated($id: ID!) {
  orderUpdated(id: $id) { id status updatedAt }
}
